import React, { useState } from 'react';
import AddTrip from './AddTrip';
import FamilyList from './FamilyList';
import AddExpense from './AddExpense';
import ExpenseList from './ExpenseList';
import TripSummary from './TripSummary';

const Dashboard = () => {
  const [trip, setTrip] = useState(null);
  const [expenses, setExpenses] = useState([]);

  const handleAddTrip = (newTrip) => {
    setTrip(newTrip);
    setExpenses([]); // Reset expenses when a new trip is added
  };

  const handleAddExpense = (expense) => {
    setExpenses([...expenses, expense]);
  };

  return (
    <div style={{ padding: '20px' }}>
      <AddTrip onAddTrip={handleAddTrip} />

      {trip && (
        <>
          <h2 style={{ marginTop: '30px' }}>Trip: {trip.tripName}</h2>

          <FamilyList familyMembers={trip.familyMembers} />

          <AddExpense
            addExpense={handleAddExpense}
            familyMembers={trip.familyMembers}
          />

          <ExpenseList expenses={expenses} />

          <TripSummary
            familyMembers={trip.familyMembers}
            expenses={expenses}
          />
        </>
      )}
    </div>
  );
};

export default Dashboard;
